using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
public class CompletionSmokeTest:MonoBehaviour {
 public DriveSession session;bool ok=true;StringBuilder report=new StringBuilder();
 void Check(bool value,string name){ok&=value;report.AppendLine((value?"PASS ":"FAIL ")+name);File.WriteAllText("artifacts/prototype-completion-test.txt","success="+ok+"\n"+report);}
 void Pose(int index){var t=session.taxi;var p=session.jobs.stops[index];t.body.velocity=t.body.angularVelocity=Vector3.zero;t.body.position=p.Kerb+Vector3.up*.65f;t.body.rotation=Quaternion.LookRotation(p.Direction);t.transform.SetPositionAndRotation(t.body.position,t.body.rotation);Physics.SyncTransforms();session.law.ResetObservation();}
 void PoseService(int kind){if(kind!=0||session.services.Stations.Count==0){Pose(session.services.indices[kind]);return;}var station=session.services.Stations[0];var t=session.taxi;t.body.velocity=t.body.angularVelocity=Vector3.zero;t.body.position=station.pump+Vector3.up*.65f;t.body.rotation=Quaternion.LookRotation(station.direction);t.transform.SetPositionAndRotation(t.body.position,t.body.rotation);Physics.SyncTransforms();session.law.ResetObservation();}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/"+name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Start(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-practiceUXTest")>=0)yield break;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-restartTest")>=0){yield return gameObject.AddComponent<CampaignRestartSmokeTest>().Run(session);yield break;}yield return new WaitForSeconds(1);var b=session.business;var jobs=session.jobs;var services=session.services;var a=b.ledger.Account;var runner=session.GetComponent<PracticeSession>();session.taxi.automated=true;session.taxi.autoBrake=true;foreach(var car in session.traffic.cars){car.Recycle();car.enabled=false;}session.roadConditions.enabled=false;
  Check(a!=null&&b.enabledCampaign,"campaign completion mode");
  b.preparing=true;Time.timeScale=0;b.StartCoroutine("PlaceAtParking");yield return null;yield return null;Check(jobs.At(services.indices[2]),"preparation starts at provisional parking");int initialCash=a.Cash;b.RequestPayment(0);Check(b.pendingPayment<0&&!b.ConfirmPayment(true)&&a.Cash==initialCash,"excluded preparation payment stays unavailable");yield return Capture("completion-preparation");b.Depart();
  var original=new LawEvent{id="completion-replay",day=1,family="right",scenario="R1",action="우회전",reason="복습 연결 검사"};original.Add("L02",LawVerdict.Violation,15);session.law.ledger.Record(original);
  Check(!runner.Begin(original),"practice blocked during business");
  for(int k=0;k<3;k++){Pose(0);yield return new WaitForSeconds(.3f);services.Toggle();Check(services.Guide(k)&&jobs.nav.hdRoute!=null,"service uses shared route "+k);PoseService(k);yield return new WaitForSeconds(.3f);services.Toggle();Check(services.open&&services.CanUse(k),"same direction service stop "+k);
   int cash=a.Cash;double seconds=b.ledger.Elapsed;Check(services.RequestAction(k),"action offered "+k);if(k==0)yield return Capture("completion-confirmation");Check(!services.ConfirmAction(false)&&a.Cash==cash&&b.ledger.Elapsed==seconds,"cancel preserves money time "+k);
   if(k<2){services.RequestAction(k);Check(services.ConfirmAction(true)&&a.Cash<cash,"confirmed purchase "+k);int after=a.Cash;Check(!services.ConfirmAction(true)&&a.Cash==after,"no duplicate transaction "+k);}else services.Toggle();
  }
  Pose(0);yield return new WaitForSeconds(.3f);Check(jobs.Interact(),"passenger boards");session.requests.request.DeferSafety();Pose(jobs.current.drop);yield return new WaitForSeconds(.3f);Check(jobs.Interact()&&b.passengers.Count==1&&b.passengers[0].paid>0,"passenger outcome retained");Check(b.passengers[0].request.Contains("안전상 보류"),"request retained in result");
  jobs.ClearForDay();Pose(0);yield return new WaitForSeconds(.3f);Check(jobs.Interact(),"timeout boards");Check(!b.RequestEndDay(),"occupied N is rejected");jobs.trip.Tick(100000);jobs.RecordExpiredTrip();jobs.RecordExpiredTrip();Check(jobs.trip.State==TripState.OnTrip&&b.passengers.Count==1&&b.ledger.FailedTrips==0,"timeout retains passenger until arrival");Pose(jobs.current.drop);yield return new WaitForSeconds(.3f);Check(jobs.Interact()&&b.passengers.Count==2&&b.passengers[1].paid==0&&b.ledger.FailedTrips==1,"late destination dropoff once and zero fare");Check(!jobs.Interact()&&b.ledger.FailedTrips==1,"late completion does not record twice");jobs.ClearForDay();
  Check(jobs.Accept(0),"unboarded offer before close");b.ledger.Advance(720,0);Check(!jobs.Accept(1)&&!jobs.Interact(),"closing blocks new pickup");yield return new WaitForSecondsRealtime(.3f);Check(b.ShowingSummary&&jobs.trip.State==TripState.Idle,"unboarded canceled at settlement");
  string account=JsonUtility.ToJson(a.Snapshot());double time=b.ledger.Elapsed;int score=session.law.ledger.Score(1),manner=session.manners.ledger.Score;session.law.OpenHistory();yield return Capture("completion-history-1600");Screen.SetResolution(1280,720,false);yield return new WaitForSecondsRealtime(.5f);yield return Capture("completion-history-1280");
  Check(runner.Begin(original),"real practice child launches");Check(!runner.Begin(original)&&!b.NextDay(),"duplicate practice and next day blocked");float until=Time.realtimeSinceStartup+45;while(runner.Busy&&Time.realtimeSinceStartup<until)yield return null;
  Check(!runner.Busy&&b.practices.Count==1&&b.practices[0].sourceId==original.id,"child result linked to original event");Check(account==JsonUtility.ToJson(a.Snapshot())&&time==b.ledger.Elapsed&&score==session.law.ledger.Score(1)&&manner==session.manners.ledger.Score,"practice preserves account clock law manners");Check(Time.timeScale==0&&b.ShowingSummary,"returns to paused settlement");session.law.OpenHistory(true);yield return Capture("completion-passenger-results");session.law.CloseHistory();yield return Capture("completion-settlement-1280");
  Check(b.SaveCheckpoint(),"combined checkpoint saves");var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(b.SavePath));Check(saved.passengers.Length==2&&saved.practices.Length==1&&saved.law.Length>=1,"checkpoint includes outcomes practice and law");Check(EconomyLedger.RestoreCampaign(saved.days,saved.account).TotalNet==b.ledger.TotalNet,"restored financial boundary");
  saved.passengers=null;saved.practices=null;var old=JsonUtility.FromJson<CampaignCheckpoint>(JsonUtility.ToJson(saved));Check(old.passengers==null||old.passengers.Length==0,"old v2 optional fields accepted");
  int confirmed=a.Cash;b.RequestPayment(0);Check(b.pendingPayment<0&&!b.ConfirmPayment(true)&&a.Cash==confirmed,"excluded summary payment cannot charge");
  Check(b.NextDay(),"next day after practice");Pose(0);yield return new WaitForSeconds(.3f);Check(jobs.Interact(),"last occupied trip starts");float deadline=jobs.trip.Remaining;b.ledger.RequestClose();yield return new WaitForSeconds(.3f);Check(!b.ShowingSummary&&jobs.trip.Remaining<=deadline&&jobs.trip.Remaining>deadline-2,"closing retains original trip deadline");Pose(jobs.current.drop);yield return new WaitForSeconds(.3f);Check(jobs.Interact(),"last trip dropoff");yield return new WaitForSecondsRealtime(.3f);Check(b.ShowingSummary&&b.passengers.Count==3,"settles after occupied result");
  report.AppendLine("DONE: automated scene placement and real isolated practice process; not manual play.");File.WriteAllText("artifacts/prototype-completion-test.txt","success="+ok+"\n"+report);Application.Quit(ok?0:1);
 }
}
